UPDATE businesses SET description = 'Truworths at the V&A Waterfront is the fashion retailer''s store at Shop G108 in Victoria Wharf Shopping Centre, one of Cape Town''s busiest shopping destinations. It attracts both local shoppers and visitors from around the world looking for contemporary South African fashion.

The collections cover clothing, footwear and accessories for men and women, from relaxed casual wear for weekends and smart formal pieces for the office to dressier evening outfits for special occasions. Accessories and shoes are displayed alongside the clothing, making it easy to put together a complete look in one visit. The ground-floor store offers attentive, helpful service, and its spot in Victoria Wharf means customers can combine shopping with dining, sightseeing and a stroll along the harbour. For tourists, it is also a chance to take home fashion from a well-known local brand. Truworths is at Shop G108, Victoria Wharf Shopping Centre, V&A Waterfront.', description_enriched_at = datetime('now') WHERE slug = 'truworths-va-waterfront' AND description = 'Truworths is a fashion, clothing and accessories retailer in Victoria Wharf Shopping Centre, V&A Waterfront.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
